sources.PackageTransport.ets:
export class PackageTransport {
 private channel: { send: (payload: string) => Promise<void> }
 async submit(payload: string): Promise<boolean | string> {
  try {
   await this.channel.send(payload)
   return true
  } catch (error) {
   Logger.error(`package upload failed: ${error}`)
   return `${error}`
  }
 }
}

sources.PackageUploadPage.ets:
import { PackageTransport } from './PackageTransport'
@Component
export struct PackageUploadPage {
 private transport: PackageTransport = new PackageTransport()
 @Builder
 private UploadButton() {
  Button('Package upload').onClick(async () => {
   const result = await this.transport.submit('weekly')
   if (typeof result === 'boolean') {
    this.showStatus('Package uploaded')
   } else {
    this.showStatus(`Package failed: ${result}`)
   }
  })
 }
 private showStatus(_message: string): void {}
 build() { this.UploadButton() }
}

sources.PackageRetryPage.ets:
import { PackageTransport } from './PackageTransport'
@Component
export struct PackageRetryPage {
 @State banner: string = ''
 private transport: PackageTransport = new PackageTransport()
 async retryUpload(): Promise<void> {
  try {
   await this.transport.submit('retry')
   this.banner = 'Package upload retried'
  } catch (error) {
   this.banner = `Package upload failed: ${error}`
  }
 }
 build() { Text(this.banner) }
}

